"""Fresh postrelease check of the printed O(-S) ancillary cohomology.

The preproof construction used a global character line.  The explicit local
equivariant module map e -> z identifies its restriction with O(-S); the
global cohomology below is calculated for the printed O(-S), separately.
The Laurent inequalities are derived from the two actual chart modules.
"""
import json
from math import comb

# On U_0, Omega(-{0}) is generated by z dz: exponents >= 1.
# On U_infinity, regular dz has exponents <= -2 in the z chart.
# Thus the Cech quotient has exactly the exponents -1 and 0.
laurent_exponents = list(range(-1, 1))
pullback_weights = [k + 1 for k in laurent_exponents]
assert laurent_exponents == [-1, 0] and pullback_weights == [0, 1]

# Only weight zero survives for every m>=3.  Translation on the abelian
# surface acts trivially on H^q(O), with dimensions (1,2,1).
abelian = [comb(2, q) for q in range(3)]
global_dimensions = [0] + abelian
thick_dimensions = [3 * n for n in abelian]
assert global_dimensions == [0, 1, 2, 1]
assert thick_dimensions == [3, 6, 3]
print(json.dumps({
    "timing": "after target proof release",
    "method": "exact Laurent chart-module quotient and graded Kunneth convolution",
    "chart_0_exponents": "k >= 1",
    "chart_infinity_exponents": "k <= -2",
    "quotient_basis": ["dz/z", "dz"],
    "pullback_character_weights": pullback_weights,
    "invariant_dimension_for_every_m_ge_3": 1,
    "support_dimensions": [0, 0, 0],
    "full_fibre_dimensions": thick_dimensions,
    "global_dimensions_for_printed_O_minus_S": global_dimensions,
    "local_bundle_comparison": "equivariant module isomorphism e -> z on T times the zero-disc",
    "global_bundle_equality_claimed": False,
    "extra_event_proposed": False,
}, indent=2))
